/// The SHA-256 of `bytes`, as sixty-four lower-case hexadecimal digits.
///
/// The same string `sha256sum` prints, which is the point: a person auditing an approval record does
/// not have to run this crate to check it.
#[must_use]
pub fn sha256_hex(bytes: &[u8]) -> String {
    let digest = sha256(bytes);
    let mut hex = String::with_capacity(64);
    for byte in digest {
        hex.push(char::from_digit(u32::from(byte >> 4), 16).unwrap_or('0'));
        hex.push(char::from_digit(u32::from(byte & 0x0f), 16).unwrap_or('0'));
    }
    hex
}

/// The raw thirty-two byte digest of `bytes`.
#[must_use]
pub fn sha256(bytes: &[u8]) -> [u8; 32] {
    let mut state = INITIAL;

    // The padded message is the input, a `0x80`, zeroes up to 56 modulo 64, then the length in bits
    // as a big-endian `u64`. Only the **tail** is copied: a baseline image is megabytes and every
    // check hashes all of them, so the whole-message copy a naive padding does would be the most
    // expensive thing in the suite.
    let bit_length = (bytes.len() as u64).wrapping_mul(8);
    let remainder = bytes.len() % 64;
    let (whole, partial) = bytes.split_at(bytes.len() - remainder);
    let mut tail = Vec::with_capacity(128);
    tail.extend_from_slice(partial);
    tail.push(0x80);
    while tail.len() % 64 != 56 {
        tail.push(0);
    }
    tail.extend_from_slice(&bit_length.to_be_bytes());

    for block in whole.as_chunks::<64>().0 {
        compress(&mut state, block);
    }
    for block in tail.as_chunks::<64>().0 {
        compress(&mut state, block);
    }

    let mut digest = [0u8; 32];
    for (word, slot) in state.iter().zip(digest.as_chunks_mut::<4>().0) {
        *slot = word.to_be_bytes();
    }
    digest
}

/// One sixty-four byte block, folded into `state`.
fn compress(state: &mut [u32; 8], block: &[u8; 64]) {
    let mut schedule = [0u32; 64];
    for (index, word) in block.as_chunks::<4>().0.iter().enumerate().take(16) {
        schedule[index] = u32::from_be_bytes(*word);
    }
    for index in 16..64 {
        let s0 = schedule[index - 15].rotate_right(7)
            ^ schedule[index - 15].rotate_right(18)
            ^ (schedule[index - 15] >> 3);
        let s1 = schedule[index - 2].rotate_right(17)
            ^ schedule[index - 2].rotate_right(19)
            ^ (schedule[index - 2] >> 10);
        schedule[index] = schedule[index - 16]
            .wrapping_add(s0)
            .wrapping_add(schedule[index - 7])
            .wrapping_add(s1);
    }

    let [mut a, mut b, mut c, mut d, mut e, mut f, mut g, mut h] = *state;
    for index in 0..64 {
        let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
        let choose = (e & f) ^ ((!e) & g);
        let temporary1 = h
            .wrapping_add(s1)
            .wrapping_add(choose)
            .wrapping_add(ROUND[index])
            .wrapping_add(schedule[index]);
        let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
        let majority = (a & b) ^ (a & c) ^ (b & c);
        let temporary2 = s0.wrapping_add(majority);
        h = g;
        g = f;
        f = e;
        e = d.wrapping_add(temporary1);
        d = c;
        c = b;
        b = a;
        a = temporary1.wrapping_add(temporary2);
    }

    for (slot, value) in state.iter_mut().zip([a, b, c, d, e, f, g, h]) {
        *slot = slot.wrapping_add(value);
    }
}
